#!/usr/bin/env bash
#
# Regenerates the Go, TypeScript and Rust code of every message contract in
# shared/contracts/*/openapi.yaml. Each operation names the languages that consume it
# (`x-consumers`), and a language gets code for those operations and the schemas they
# reach, in one package or file, so nothing is generated that no code of that language
# reads. With --check it changes nothing and exits non-zero if any generated file
# differs from what is committed.
#
#   gen-schemas.sh           rewrite the generated files
#   gen-schemas.sh --check   generate into a temporary directory and diff
#
# Pinned tools: ogen (a `tool` line in scripts/contracts/go.mod),
# openapi-typescript, ajv and @redocly/openapi-core (scripts/contracts/
# package.json and bun.lock) and cargo-typify (TYPIFY_VERSION below, installed
# under scripts/contracts/.tools). jq and rustfmt come from the toolchain.

set -euo pipefail

readonly TYPIFY_VERSION="0.10.1"

cd "$(git rev-parse --show-toplevel)"

check=false
case "${1:-}" in
  "") ;;
  --check) check=true ;;
  *)
    echo "usage: $0 [--check]" >&2
    exit 2
    ;;
esac

# Where each language's generated code lives, in the package that consumes it. Only
# the generated files are replaced: `*_gen.go` in the Go directory, and the two
# `messages*.gen.ts` files in the TypeScript directory.
readonly GO_DIR="shared/common/golang/messages"
readonly GO_PACKAGE="messages"
readonly TS_DIR="shared/common/typescript/cloudevents"
readonly TS_TYPES="messages.gen.ts"
readonly TS_VALIDATORS="messages.validate.gen.ts"
readonly RUST_FILE="shared/common/rust/cloudevents/src/messages_gen.rs"

tools=scripts/contracts
if ! cargo install --list --root "$tools/.tools" 2>/dev/null | grep -q "^cargo-typify v$TYPIFY_VERSION"; then
  rm -rf "$tools/.tools"
  cargo install --locked cargo-typify --version "$TYPIFY_VERSION" --root "$tools/.tools" >&2
fi
export PATH="$PWD/$tools/node_modules/.bin:$PWD/$tools/.tools/bin:$PATH"

out="$(mktemp -d)"
trap 'rm -rf "$out"' EXIT

sources=(shared/contracts/*/openapi.yaml)
docs="$out/docs"
header="Generated by scripts/gen-schemas.sh from shared/contracts. Do not edit."

# One document per language, holding only what that language consumes; a language no operation names gets none.
bun "$tools/bundle.ts" "$docs" "${sources[@]}"

# Every fixture agrees with the document, including those of messages no language consumes yet.
bun "$tools/fixtures.ts" "$docs/all.json" shared/contracts/*/fixtures

# The operation path is the subject, and a request that is a CloudEvent fixes the same `type`.
# A plain JSON request has no `type` and an operation may have no request at all.
jq -e '. as $d | .paths | to_entries | all(.[]; (.value.post.requestBody.content["application/json"].schema["$ref"] // null) as $r | if $r == null then true else ($d.components.schemas[($r | split("/")[-1])].properties.type.enum[0]) as $t | $t == null or "/" + $t == .key end)' "$docs/all.json" >/dev/null ||
  { echo "gen-schemas: an operation path is not the \`type\` its request fixes" >&2; exit 1; }

# Go: types, enums, tagged unions and validators; no client or server.
if [ -f "$docs/go.json" ]; then
  mkdir -p "$out/$GO_DIR"
  (cd "$tools" && go tool ogen -config ogen.yaml -package "$GO_PACKAGE" -target "$out/$GO_DIR" -clean "$docs/go.json") 2>"$out/ogen.log" || { cat "$out/ogen.log" >&2; exit 1; }
  # ogen skips what it cannot generate, with only a log line; a skipped operation or schema must fail the run.
  if grep -q "Skipping" "$out/ogen.log"; then
    cat "$out/ogen.log" >&2
    echo "gen-schemas: ogen skipped part of the Go contracts" >&2
    exit 1
  fi
  for schema in $(jq -r '.components.schemas | keys[]' "$docs/go.json"); do
    grep -q "^type $schema " "$out/$GO_DIR"/oas_schemas_gen.go || { echo "gen-schemas: ogen generated no Go type for $schema" >&2; exit 1; }
  done
  sed -i "s|^// Code generated by ogen, DO NOT EDIT\.|// Code generated by scripts/gen-schemas.sh (ogen) from shared/contracts. DO NOT EDIT.|" "$out/$GO_DIR"/*.go
fi

# TypeScript: types with run-time enums, and precompiled Ajv validators.
if [ -f "$docs/ts.json" ]; then
  mkdir -p "$out/$TS_DIR"
  openapi-typescript "$docs/ts.json" --root-types --enum --default-non-nullable false -o "$out/$TS_DIR/$TS_TYPES" >/dev/null
  sed -i "1i // $header" "$out/$TS_DIR/$TS_TYPES"
  bun "$tools/ajv-standalone.ts" "$docs/ts.json" "$TS_TYPES" "$out/$TS_DIR/$TS_VALIDATORS"
  sed -i "1i // $header\n// @ts-nocheck" "$out/$TS_DIR/$TS_VALIDATORS"
fi

# Rust: typify reads JSON Schema definitions, so the document's components are lifted out first. The document
# is embedded for the run-time validator.
if [ -f "$docs/rust.json" ]; then
  mkdir -p "$out/$(dirname "$RUST_FILE")"
  jq -f "$tools/typify-prep.jq" "$docs/rust.json" | sed 's|#/components/schemas/|#/definitions/|g' >"$out/rust.defs.json"
  cargo typify "$out/rust.defs.json" -B --output "$out/$RUST_FILE" >/dev/null 2>&1
  {
    echo "// $header"
    cat "$out/$RUST_FILE"
    printf '\n/// The contract document the run-time validator reads.\npub const DOCUMENT: &str = r####"%s"####;\n' "$(jq -c . "$docs/rust.json")"
  } >"$out/$RUST_FILE.tmp"
  mv "$out/$RUST_FILE.tmp" "$out/$RUST_FILE"
  rustfmt --edition 2021 "$out/$RUST_FILE"
fi

# The first lines of a difference; the validators are one very long line each.
show_diff() {
  diff -uN "$@" | cut -c1-160 | head -n 30
  return "${PIPESTATUS[0]}"
}

# Every generated file, as committed and as just generated; a file on one side only is a difference or a stale file.
generated_files() {
  {
    ls "$GO_DIR"/*_gen.go "$TS_DIR/$TS_TYPES" "$TS_DIR/$TS_VALIDATORS" "$RUST_FILE" 2>/dev/null || true
    (cd "$out" && ls "$GO_DIR"/*_gen.go "$TS_DIR/$TS_TYPES" "$TS_DIR/$TS_VALIDATORS" "$RUST_FILE" 2>/dev/null) || true
  } | sort -u
}

stale=0
while read -r f; do
  if $check; then
    show_diff "$f" "$out/$f" >&2 || stale=1
  elif [ -f "$out/$f" ]; then
    mkdir -p "$(dirname "$f")"
    cp "$out/$f" "$f"
  else
    rm -f "$f"
  fi
done < <(generated_files)
if [ "$stale" -ne 0 ]; then
  echo "gen-schemas: generated files are out of date; run scripts/gen-schemas.sh and commit the result" >&2
  exit 1
fi
